1. using System.ComponentModel;
2. using ModelContextProtocol.Server;
3. 
4. /// <summary>
5. /// Sample MCP tools for demonstration purposes.
6. /// These tools can be invoked by MCP clients to perform various operations.
7. /// </summary>
8. internal class RandomNumberTools
9. {
10.     [McpServerTool]
11.     [Description("Generates a random number between the specified minimum and maximum values.")]
12.     public int GetRandomNumber(
13.         [Description("Minimum value (inclusive)")] int min = 0,
14.         [Description("Maximum value (exclusive)")] int max = 100)
15.     {
16.         return Random.Shared.Next(min, max);
17.     }
18. }
19.

