using System.ComponentModel;
using ModelContextProtocol.Server;

/// <summary>
/// MCP resources that expose configuration data to clients.
/// </summary>
[McpServerResourceType]
internal class ConfigResources
{
    /// <summary>
    /// Returns the current application configuration as JSON.
    /// This is a static resource with a fixed URI.
    /// </summary>
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app-settings",
        Title = "Application Settings", MimeType = "application/json")]
    [Description("Returns the current application configuration.")]
    public static string GetAppSettings()
    {
        var settings = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxConnections = 100,
            Features = new { Logging = true, Metrics = true, HealthChecks = true }
        };

        return System.Text.Json.JsonSerializer.Serialize(settings,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }

    /// <summary>
    /// A resource template that returns configuration for a specific section.
    /// Clients can request e.g. config://app/section/logging.
    /// </summary>
    [McpServerResource(UriTemplate = "config://app/section/{sectionName}", Name = "config-section",
        Title = "Configuration Section", MimeType = "application/json")]
    [Description("Returns configuration for a specific section by name.")]
    public static string GetConfigSection(string sectionName)
    {
        var sections = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
        {
            ["logging"] = new { Level = "Information", OutputTemplate = "{Timestamp} [{Level}] {Message}" },
            ["database"] = new { Provider = "SQLite", ConnectionTimeout = 30 },
            ["cache"] = new { Enabled = true, ExpirationMinutes = 15 }
        };

        if (!sections.TryGetValue(sectionName, out var section))
        {
            return System.Text.Json.JsonSerializer.Serialize(
                new { Error = $"Unknown section: {sectionName}", AvailableSections = sections.Keys });
        }

        return System.Text.Json.JsonSerializer.Serialize(section,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

